rule_structure:
{
  "demand_type": {
    "label": " ",
    "value": {
      "label": "Demand Type",
      "type": "dropdown",
      "value": [
        {
          "ia_forecast": "IA Forecast"
        },
        {
          "fixed_inventory_push": "Fixed Inventory Push"
        },
        {
          "last_year_forecast": "Last Year Forecast"
        }
      ],
      "dependencies": [
        {
          "label": "IA Forecast",
          "value": {
            "type": "-"
          },
          "show_on": "ia_forecast",
          "default_value": "-"
        },
        {
          "label": "Fixed Inventory Push",
          "value": {
            "type": "percent"
          },
          "show_on": "fixed_inventory_push",
          "default_value": "10%",
          "min": 0,
          "max": 100
        },
        {
          "label": "Last Year Forecast",
          "value": {
            "type": "-"
          },
          "show_on": "last_year_forecast",
          "default_value": "-"
        }
      ]
    }
  }
}
